def find_path(graph, start, goal):
    # A helper function to check if a node has been visited
    def has_visited(visited, node):
        return node in visited

    # A helper function for the recursive path search
    def search(visited, current):
        if current == goal:
            return [current]
        visited.add(current)
        for neighbor in graph.get(current, []):
            if not has_visited(visited, neighbor):
                path = search(visited, neighbor)
                if path:
                    return [current] + path
        return None

    # Start the search
    return search(set(), start)
